// Impede Open Redirect (CWE-601): só aceita path relativo ao próprio site; qualquer outro host/protocolo cai no fallback.
tw.sanitizarReturnUrl = function (returnUrl, urlPadrao) {
	var urlFallback = urlPadrao || sophiaConfig.serviceBaseUrl;

	if (String.isNullOrEmpty(returnUrl)) {
		return urlFallback;
	}

	try {
		var urlResolvida = new URL(decodeURIComponent(returnUrl), window.location.origin);
		return urlResolvida.origin === window.location.origin
			? urlResolvida.pathname + urlResolvida.search + urlResolvida.hash
			: urlFallback;
	} catch (e) {
		return urlFallback;
	}
};

